// The committed extract of Fonecta's dataset (stage C10): 17 demo storylines + the 15 shopping
// centres, with profiles, exception history, calendar and peer rows. Generated by
// scripts/import-fonecta.mjs from FONECTA/FONECTA_CONNECT_SUGGESTS_2026 (not committed).
//
// The cast lives here so the seed route and later stages (C11, C12) read one typed object.

import demo from "./demo.json";
import type {
  Business,
  HolidayHistoryEntry,
  PeerBenchmark,
  Profile,
  PublisherSuggestion,
  Review,
  SpecialDay,
} from "@/types";

export interface FonectaDemo {
  source: { dataset: string; licence: string; built_by: string };
  counts: {
    businesses: number;
    profiles: number;
    holiday_history: number;
    special_days: number;
    peers: number;
    reviews: number;
    publisher_suggestions: number;
  };
  businesses: Business[];
  profiles: Profile[];
  holiday_history: HolidayHistoryEntry[];
  special_days: SpecialDay[];
  peers: PeerBenchmark[];
  reviews: Review[];
  publisher_suggestions: PublisherSuggestion[];
}

// The JSON has plain strings where the types use unions (category, country, channel, …); the
// importer validates them before writing, so one cast here is enough.
export const fonectaDemo = demo as unknown as FonectaDemo;
